<script>
document.addEventListener('DOMContentLoaded', () => {
    const all = document.querySelector('[data-check-all]');
    if (!all) return;
    all.addEventListener('change', () => document.querySelectorAll('[data-row-check]').forEach((box) => { box.checked = all.checked; }));
});
</script>
